"use client";

import {
  useEffect,
  useState,
} from "react";

import {
  ChevronLeft,
  ChevronRight,
} from "lucide-react";

import MockTestCard from "./MockTestCard";

const PAGE_SIZE = 10;

export default function MockTestList({
  cid,
  uid = 0,
  filter = 0,
  examName,
  shortName,
  governmentExamsSlug,
}) {
  const [
    tests,
    setTests,
  ] = useState([]);

  const [
    loading,
    setLoading,
  ] = useState(true);

  const [
    error,
    setError,
  ] = useState("");

  const [
    currentOffset,
    setCurrentOffset,
  ] = useState(0);

  const [
    nextOffset,
    setNextOffset,
  ] = useState(null);

  const [
    highestPage,
    setHighestPage,
  ] = useState(1);

  const currentPage =
    Math.floor(
      currentOffset /
        PAGE_SIZE
    ) + 1;

  /* =======================================================
     LOAD
  ======================================================= */

  async function loadTests(
    offset = 0
  ) {
    if (!cid) {
      setError(
        "Course ID is missing."
      );

      setLoading(false);

      return;
    }

    try {
      setLoading(true);
      setError("");

      const params =
        new URLSearchParams({
          cid:
            String(cid),

          uid:
            String(uid),

          offset:
            String(offset),

          filter:
            String(filter),
        });

      const response =
        await fetch(
          `/api/mock-tests/list?${params.toString()}`,
          {
            cache:
              "no-store",
          }
        );

      const result =
        await response.json();

      if (!response.ok) {
        throw new Error(
          result?.message ||
            "Unable to load mock tests."
        );
      }

      const testData =
        Array.isArray(
          result?.data
        )
          ? result.data
          : [];

      const apiNextOffset =
        result?.nextoffset ??
        result?.nextOffset ??
        null;

      setTests(
        testData
      );

      setCurrentOffset(
        offset
      );

      setNextOffset(
        apiNextOffset
      );

      const loadedPage =
        Math.floor(
          offset /
            PAGE_SIZE
        ) + 1;

      const discoveredPage =
        apiNextOffset != null
          ? loadedPage + 1
          : loadedPage;

      setHighestPage(
        (previous) =>
          Math.max(
            previous,
            discoveredPage
          )
      );
    } catch (error) {
      console.error(
        `Mock tests for ${examName}:`,
        error
      );

      setTests([]);

      setNextOffset(
        null
      );

      setError(
        error?.message ||
          "Unable to load mock tests."
      );
    } finally {
      setLoading(false);
    }
  }

  /* =======================================================
     RELOAD WHEN MAIN COURSE CHANGES
  ======================================================= */

  useEffect(() => {
    if (!cid) {
      return;
    }

    setTests([]);

    setCurrentOffset(0);

    setNextOffset(
      null
    );

    setHighestPage(1);

    loadTests(0);
  }, [
    cid,
    uid,
    filter,
  ]);

  /* =======================================================
     PAGINATION
  ======================================================= */

  function scrollToList() {
    window.scrollTo({
      top: 0,
      behavior:
        "smooth",
    });
  }

  async function handlePageClick(
    page
  ) {
    if (
      loading ||
      page < 1 ||
      page === currentPage
    ) {
      return;
    }

    const offset =
      (page - 1) *
      PAGE_SIZE;

    await loadTests(
      offset
    );

    scrollToList();
  }

  async function handlePrevious() {
    if (
      loading ||
      currentPage <= 1
    ) {
      return;
    }

    await handlePageClick(
      currentPage - 1
    );
  }

  async function handleNext() {
    if (
      loading ||
      nextOffset == null
    ) {
      return;
    }

    await loadTests(
      Number(
        nextOffset
      )
    );

    scrollToList();
  }

  const pageNumbers =
    Array.from(
      {
        length:
          highestPage,
      },
      (_, index) =>
        index + 1
    );

  /* =======================================================
     LOADING
  ======================================================= */

  if (
    loading &&
    tests.length === 0
  ) {
    return (
      <div
        className="
          grid
          gap-5
          md:grid-cols-2
          xl:grid-cols-3
        "
      >
        {Array.from({
          length: 6,
        }).map(
          (_, index) => (
            <div
              key={
                index
              }
              className="
                h-[280px]
                animate-pulse
                rounded-[24px]
                border
                border-slate-200
                bg-white
              "
            />
          )
        )}
      </div>
    );
  }

  /* =======================================================
     ERROR
  ======================================================= */

  if (error) {
    return (
      <div
        className="
          rounded-[20px]
          border
          border-rose-200
          bg-rose-50
          px-5
          py-8
          text-center
        "
      >
        <p
          className="
            text-[13px]
            font-bold
            text-rose-600
          "
        >
          {error}
        </p>
      </div>
    );
  }

  /* =======================================================
     EMPTY
  ======================================================= */

  if (
    tests.length === 0
  ) {
    return (
      <div
        className="
          rounded-[20px]
          border
          border-slate-200
          bg-white
          px-5
          py-12
          text-center
        "
      >
        <p
          className="
            text-[13px]
            font-bold
            text-slate-500
          "
        >
          No {examName} mock
          tests are currently
          available.
        </p>
      </div>
    );
  }

  return (
    <section>
      <div
        className={`
          grid
          gap-5
          md:grid-cols-2
          xl:grid-cols-3

          ${
            loading
              ? "pointer-events-none opacity-60"
              : ""
          }
        `}
      >
        {tests.map(
          (test) => (
            <MockTestCard
              key={
                test?.id
              }
              test={
                test
              }
              uid={
                uid
              }
              cid={
                cid
              }
              examName={
                examName
              }
              shortName={
                shortName
              }
              governmentExamsSlug={
                governmentExamsSlug
              }
            />
          )
        )}
      </div>

      <div
        className="
          mt-9
          flex
          flex-wrap
          items-center
          justify-center
          gap-2
        "
      >
        <button
          type="button"
          onClick={
            handlePrevious
          }
          disabled={
            loading ||
            currentPage === 1
          }
          className="
            inline-flex
            h-10
            items-center
            justify-center
            gap-1.5
            rounded-[11px]
            border
            border-slate-200
            bg-white
            px-4
            text-[11px]
            font-bold
            text-slate-600
            shadow-sm
            transition
            hover:bg-blue-50
            disabled:cursor-not-allowed
            disabled:opacity-40
          "
        >
          <ChevronLeft
            size={14}
          />

          Previous
        </button>

        <div
          className="
            flex
            items-center
            gap-2
          "
        >
          {pageNumbers.map(
            (page) => {
              const isActive =
                page ===
                currentPage;

              return (
                <button
                  key={
                    page
                  }
                  type="button"
                  onClick={() =>
                    handlePageClick(
                      page
                    )
                  }
                  disabled={
                    loading
                  }
                  aria-current={
                    isActive
                      ? "page"
                      : undefined
                  }
                  className={`
                    flex
                    h-10
                    w-10
                    items-center
                    justify-center
                    rounded-[11px]
                    border
                    text-[11px]
                    font-extrabold
                    transition

                    ${
                      isActive
                        ? `
                            border-[#164fa5]
                            bg-[#164fa5]
                            text-white
                          `
                        : `
                            border-slate-200
                            bg-white
                            text-slate-600
                            hover:bg-blue-50
                          `
                    }
                  `}
                >
                  {page}
                </button>
              );
            }
          )}
        </div>

        <button
          type="button"
          onClick={
            handleNext
          }
          disabled={
            loading ||
            nextOffset == null
          }
          className="
            inline-flex
            h-10
            items-center
            justify-center
            gap-1.5
            rounded-[11px]
            border
            border-[#164fa5]
            bg-[#164fa5]
            px-4
            text-[11px]
            font-bold
            text-white
            transition
            hover:bg-[#0b216c]
            disabled:cursor-not-allowed
            disabled:opacity-40
          "
        >
          Next

          <ChevronRight
            size={14}
          />
        </button>
      </div>
    </section>
  );
}

"use client";

import {
  useEffect,
  useRef,
  useState,
} from "react";

import {
  useRouter,
} from "next/navigation";

import ExamHero from "./ExamHero";
import ExamTimer from "./ExamTimer";
import ExamProgress from "./ExamProgress";
import ExamQuestionRange from "./ExamQuestionRange";
import ExamQuestions from "./ExamQuestions";
import ExamPagination from "./ExamPagination";
import ExamPause from "./ExamPause";
import ExamSubmit from "./ExamSubmit";
import ExamResult from "./ExamResult";
import ExamEmpty from "./ExamEmpty";

import useExamController from "./hooks/useExamController";

import PyqResultModal from "@/components/PyqResultModal";

import {
  clearGuestExamHandoff,
  readGuestExamHandoff,
} from "@/lib/guestExamHandoff";

export default function ExamClient({
  exam,
  examId,
  questions = [],
  imagePath = "",
  uid = 0,
  cid,
  examType = "pqp",
  lastPosition,
  initialPauseId = null,
  governmentExamsSlug = "",
  guestAction = "",
}) {
  const router = useRouter();

  const id = examId ?? exam?.id;

  const handoff = [
    "pause",
    "submit",
  ].includes(guestAction);

  const [restored, setRestored] = useState(
    !handoff
  );

  const [
    restoreError,
    setRestoreError,
  ] = useState("");

  const restoredOnce = useRef(false);
  const appliedOnce = useRef(false);
  const autoSubmitted = useRef(false);

  const controller = useExamController({
    exam,
    examId: id,
    questions,
    uid,
    cid,
    examType,
    lastPosition,
    initialPauseId,
    governmentExamsSlug,
    guestAction,
  });

  useEffect(() => {
    restoredOnce.current = false;
    appliedOnce.current = false;
    autoSubmitted.current = false;

    setRestored(!handoff);
    setRestoreError("");
  }, [
    id,
    guestAction,
    handoff,
  ]);

  /* RESTORE BEFORE SAVING */

  useEffect(() => {
    if (
      !handoff ||
      restoredOnce.current
    ) {
      return;
    }

    const timer = window.setTimeout(() => {
      if (restoredOnce.current) return;

      restoredOnce.current = true;

      try {
        const saved = readGuestExamHandoff({
          examId: id,
          examType,
          governmentExamsSlug,
        });

        if (
          !saved ||
          saved.action !== guestAction
        ) {
          throw new Error(
            "Saved exam progress could not be found. Return to the original exam tab."
          );
        }

        controller.restoreGuestAttempt(saved);
        setRestored(true);
      } catch (error) {
        setRestoreError(
          error.message ||
          "Unable to restore this exam."
        );
      }
    }, 0);

    return () => window.clearTimeout(timer);
  }, [
    handoff,
    id,
    examType,
    governmentExamsSlug,
    guestAction,
    controller.restoreGuestAttempt,
  ]);

  /* SAVE AFTER LOGIN / PROFILE SETUP */

  useEffect(() => {
    if (
      !handoff ||
      !restored ||
      restoreError ||
      !controller.restoreReady ||
      appliedOnce.current
    ) {
      return;
    }

    appliedOnce.current = true;

    // Already saved before refresh.
    if (controller.submitted) return;

    if (guestAction === "submit") {
      controller.handleSubmit();
    } else {
      controller.handlePause();
    }
  }, [
    handoff,
    restored,
    restoreError,
    guestAction,
    controller.restoreReady,
    controller.submitted,
    controller.handleSubmit,
    controller.handlePause,
  ]);

  /* AUTOMATIC FINISH */

  useEffect(() => {
    if (
      !restored ||
      restoreError ||
      handoff ||
      !controller.timerFinished ||
      controller.submitted ||
      controller.saving ||
      autoSubmitted.current
    ) {
      return;
    }

    autoSubmitted.current = true;
    controller.handleSubmit();
  }, [
    restored,
    restoreError,
    handoff,
    controller.timerFinished,
    controller.submitted,
    controller.saving,
    controller.handleSubmit,
  ]);

  function viewAttempted() {
    if (!governmentExamsSlug) return;

    try {
      clearGuestExamHandoff();
    } catch {
      // Attempt is already saved to the backend.
    }

    router.push(
      `/dashboard/${encodeURIComponent(
        governmentExamsSlug
      )}/exam-attempted`
    );
  }

  if (restoreError) {
    return (
      <p
        role="alert"
        className="rounded-xl bg-red-50 p-5 text-red-700"
      >
        {restoreError}
      </p>
    );
  }

  if (
    !restored ||
    !controller.restoreReady
  ) {
    return (
      <p
        role="status"
        className="rounded-xl bg-white p-5"
      >
        Restoring your completed exam…
      </p>
    );
  }

  if (!controller.totalQuestions) {
    return <ExamEmpty />;
  }

  const c = controller;

  return (
    <>
      <section className="space-y-6">
        {c.saveError && (
          <p
            role="alert"
            className="rounded-xl bg-red-50 p-4 text-red-700"
          >
            {c.saveError} Your answers are retained.
            Use the action button to retry.
          </p>
        )}

        {c.paused && (
          <p
            role="status"
            className="rounded-xl bg-amber-50 p-4"
          >
            Exam paused. Answers and remaining time
            are saved.
          </p>
        )}

        <ExamHero
          exam={exam}
          totalQuestions={c.totalQuestions}
          currentPage={c.currentPage}
          totalPages={c.totalPages}
        />

        {c.durationMinutes > 0 && (
          <div className="flex justify-end">
            <ExamTimer
              remainingSeconds={c.remainingSeconds}
              durationMinutes={c.durationMinutes}
            />
          </div>
        )}

        {c.submitted && (
          <ExamResult
            totalQuestions={c.totalQuestions}
            answeredCount={c.answeredCount}
            correctCount={c.correctCount}
            wrongCount={c.wrongCount}
          />
        )}

        <ExamProgress
          answeredCount={c.answeredCount}
          totalQuestions={c.totalQuestions}
          progress={c.progress}
        />

        <ExamQuestionRange
          startIndex={c.startIndex}
          endIndex={c.endIndex}
          totalQuestions={c.totalQuestions}
          currentPage={c.currentPage}
          unansweredCount={c.unansweredCount}
        />

        <div
          className={
            c.saving ||
              c.paused ||
              handoff ||
              c.submitted
              ? "pointer-events-none"
              : ""
          }
        >
          <ExamQuestions
            questions={c.currentQuestions}
            startIndex={c.startIndex}
            answers={c.answers}
            submitted={c.submitted}
            imagePath={imagePath}
            onAnswer={c.handleAnswer}
          />
        </div>

        <ExamPagination
          currentPage={c.currentPage}
          totalPages={c.totalPages}
          onPrevious={c.handlePreviousPage}
          onNext={c.handleNextPage}
          onPageChange={c.handlePageChange}
        />

        {!c.submitted && (
          <div className="flex flex-col gap-3 sm:flex-row sm:justify-end">
            {guestAction !== "submit" && (
              <ExamPause
                paused={c.paused}
                disabled={
                  c.timerFinished || c.saving
                }
                onPause={c.handlePause}
                saving={c.saving}
              />
            )}

            <ExamSubmit
              answeredCount={c.answeredCount}
              totalQuestions={c.totalQuestions}
              onSubmit={c.handleSubmit}
              saving={c.saving}
            />
          </div>
        )}

        {c.timerFinished && !c.submitted && (
          <p
            role="status"
            className="rounded-xl bg-red-50 p-4 text-red-700"
          >
            Exam time has ended.{" "}
            {c.saveError
              ? "Use Submit & Finish to retry."
              : "Saving your exam…"}
          </p>
        )}

        {c.submitted && (
          <button
            type="button"
            onClick={() => c.handleSubmit()}
            className="rounded-xl bg-blue-700 px-5 py-3 font-bold text-white"
          >
            Show Result
          </button>
        )}
      </section>

      <PyqResultModal
        open={c.resultModalOpen}
        result={c.submittedResult}
        examTitle={
          exam?.exam_name ??
          exam?.title ??
          "Previous Questions"
        }
        onClose={c.closeResultModal}
        onViewAnalysis={viewAttempted}
      />
    </>
  );
}

