"use client";

import {
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import {
  useRouter,
  usePathname,
} from "next/navigation";

import Link from "next/link";

import {
  calculateExamResult,
  getAttemptId,
  getResultArray,
  parseAnswers,
  savedPausedTimeToSeconds,
  timestampToMilliseconds,
} from "@/lib/examAttemptData";

import {
  saveGuestExamHandoff,
  readGuestExamHandoff,
  clearGuestExamHandoff,
  guestExamLoginRedirectPath,
} from "@/lib/guestExamHandoff";

import ExamHero from "./ExamHero";
import ExamProgress from "./ExamProgress";
import ExamQuestions from "./ExamQuestions";
import ExamPagination from "./ExamPagination";
import ExamControls from "./ExamControls";

import ExamResultModal from "@/components/ExamResultModal";

function positiveId(value) {
  const number = Number(value);

  return Number.isSafeInteger(number) && number > 0
    ? number
    : null;
}

function failed(value) {
  return [
    false,
    "false",
    0,
    "0",
    "error",
    "failed",
  ].includes(value);
}

async function post(endpoint, payload) {
  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  });

  let result;

  try {
    result = await response.json();
  } catch {
    throw new Error(
      "The exam API returned an invalid response."
    );
  }

  if (
    !response.ok ||
    !result ||
    failed(result.status)
  ) {
    const error = new Error(
      result?.message ||
      result?.msg ||
      "Unable to save the exam."
    );

    error.status = response.status;
    throw error;
  }

  return result;
}

export default function ExamClient({
  exam,
  examId,
  questions = [],
  imagePath = "",
  uid = 0,
  cid,
  slug = "",
  examSlug = "",
  examType = "twe",
  mode = "new",
  initialPauseId = null,
  governmentExamsSlug = "",
  guestAction = "",
}) {
  const router = useRouter();
  const pathname = usePathname();

  const id = examId ?? exam?.id;
  const type = "twe";

  const basePath =
    `${pathname?.startsWith("/dashboard/")
      ? "/dashboard"
      : "/government-exams-coaching"}` +
    `/${governmentExamsSlug}/topic-wise-exams`;

  const durationMinutes = Math.max(
    0,
    Number(exam?.total_minutes) || 0
  );

  const fullDuration = Math.round(
    durationMinutes * 60
  );

  const pageSize = 10;
  const totalQuestions = questions.length;

  const totalPages = Math.max(
    1,
    Math.ceil(totalQuestions / pageSize)
  );

  const isHandoff = [
    "pause",
    "submit",
  ].includes(guestAction);

  const draftKey =
    `exam_draft_${uid}_${cid}_${type}_${id}`;

  const [ready, setReady] = useState(false);

  const [
    handoffConsumed,
    setHandoffConsumed,
  ] = useState(false);

  const [restoreError, setRestoreError] = useState("");
  const [saveError, setSaveError] = useState("");
  const [answers, setAnswers] = useState({});

  const [
    remainingSeconds,
    setRemainingSeconds,
  ] = useState(fullDuration);

  const [currentPage, setCurrentPage] = useState(1);
  const [saving, setSaving] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [paused, setPaused] = useState(false);

  const [
    resultModalOpen,
    setResultModalOpen,
  ] = useState(false);

  const [
    submittedResult,
    setSubmittedResult,
  ] = useState(null);

  const lock = useRef(false);
  const autoHandled = useRef(false);
  const timeoutHandled = useRef(false);

  const snapshot = useRef({
    answers: {},
    remainingSeconds: fullDuration,
    currentPage: 1,
    startTime: 0,
    endTime: null,
    pauseId: initialPauseId,
    boundUid: null,
    submittedResult: null,
    frozen: isHandoff,
  });

  const questionIds = useMemo(
    () => questions.map((q) => String(q.id)),
    [questions]
  );

  const answerKeys = useMemo(
    () =>
      questions.map(
        (q) =>
          q.answerkey ??
          q.answer ??
          q.correct_answer ??
          q.correctAnswer ??
          q.right_answer ??
          q.ans ??
          0
      ),
    [questions]
  );

  const stats = useMemo(
    () =>
      calculateExamResult({
        answerArray: answerKeys,

        userAnswers:
          questions.map(
            (q) => answers[String(q.id)] ?? 0
          ),

        markPerCorrect: 1,
        negativeMarkPerWrong: 0.333,
      }),
    [answers, questions, answerKeys]
  );

  function storeDraft() {
    try {
      localStorage.setItem(
        draftKey,
        JSON.stringify({
          ...snapshot.current,
          questionIds,
          savedAt: Date.now(),
        })
      );
    } catch {
      // Guest login uses checked storage below.
    }
  }

  function checkpoint(action) {
    return saveGuestExamHandoff({
      ...snapshot.current,
      examId: id,
      examType: type,
      cid,
      slug,
      examSlug,
      governmentExamsSlug,
      questionIds,
      action,
    });
  }

  /* RESTORE ANSWERS BEFORE SUBMITTING */

  useEffect(() => {
    let cancelled = false;

    setReady(false);
    setRestoreError("");

    async function restore() {
      try {
        let saved = null;

        if (isHandoff) {
          saved = readGuestExamHandoff({
            examId: id,
            examType: type,
            governmentExamsSlug,
          });

          if (
            !saved ||
            saved.action !== guestAction
          ) {
            throw new Error(
              "Saved Topic Wise answers could not be found. Reopen the original exam tab."
            );
          }

          if (Number(saved.cid) !== Number(cid)) {
            throw new Error(
              "Saved topic-wise course does not match this exam."
            );
          }

          if (
            saved.boundUid &&
            Number(saved.boundUid) !== Number(uid)
          ) {
            throw new Error(
              "This saved attempt belongs to another account."
            );
          }
        } else {
          try {
            saved = JSON.parse(
              localStorage.getItem(draftKey) || "null"
            );
          } catch {
            saved = null;
          }

          if (
            saved &&
            (
              !saved.savedAt ||
              Date.now() - saved.savedAt > 86400000
            )
          ) {
            saved = null;
          }
        }

        if (!isHandoff && mode === "resume") {
          if (
            !positiveId(uid) ||
            !positiveId(initialPauseId)
          ) {
            throw new Error(
              "Sign in and reopen the paused exam."
            );
          }

          const result = await post(
            "/api/exam-attempt/analytics-details",
            {
              cid,
              id: initialPauseId,
              exam_type: type,
            }
          );

          const row = getResultArray(result)[0];

          if (!row) {
            throw new Error(
              "Saved exam answers were not returned."
            );
          }

          if (
            row.exam_id != null &&
            String(row.exam_id) !== String(id)
          ) {
            throw new Error(
              "The paused attempt belongs to another exam."
            );
          }

          if (
            row.cid != null &&
            Number(row.cid) !== Number(cid)
          ) {
            throw new Error(
              "The paused attempt belongs to another course."
            );
          }

          const values = parseAnswers(row.user_answers);

          if (values.length !== questions.length) {
            throw new Error(
              "The saved answer array does not match this question paper."
            );
          }

          saved = {
            answers: Object.fromEntries(
              questions.map((q, index) => [
                String(q.id),
                values[index] ?? 0,
              ])
            ),

            questionIds,

            remainingSeconds:
              savedPausedTimeToSeconds(
                row.paused_time,
                fullDuration
              ),

            startTime:
              timestampToMilliseconds(
                row.start_time ??
                row.startTime ??
                row.started_at ??
                row.created_at
              ) ?? Date.now(),

            currentPage:
              String(saved?.pauseId) ===
                String(initialPauseId)
                ? saved.currentPage
                : 1,

            pauseId: initialPauseId,
            boundUid: Number(uid),
          };
        }

        if (saved) {
          if (
            !saved.answers ||
            typeof saved.answers !== "object" ||
            Array.isArray(saved.answers)
          ) {
            throw new Error(
              "Saved Topic Wise answers are invalid."
            );
          }

          if (
            JSON.stringify(saved.questionIds) !==
            JSON.stringify(questionIds)
          ) {
            throw new Error(
              "The Topic Wise question paper changed. This draft cannot be restored safely."
            );
          }

          if (
            !Number.isFinite(
              Number(saved.remainingSeconds)
            ) ||
            Number(saved.remainingSeconds) < 0 ||
            Number(saved.remainingSeconds) > fullDuration
          ) {
            throw new Error(
              "Saved exam time is invalid."
            );
          }
        }

        if (cancelled) return;

        snapshot.current = saved
          ? {
            answers: { ...saved.answers },

            remainingSeconds:
              Number(saved.remainingSeconds),

            currentPage: Math.max(
              1,
              Math.min(
                totalPages,
                Number(saved.currentPage) || 1
              )
            ),

            startTime:
              timestampToMilliseconds(
                saved.startTime
              ) ?? Date.now(),

            endTime: saved.endTime ?? null,
            pauseId: saved.pauseId ?? initialPauseId,
            boundUid: saved.boundUid ?? null,

            submittedResult:
              saved.submittedResult ?? null,

            frozen:
              isHandoff ||
              Boolean(saved.submittedResult) ||
              Boolean(saved.endTime),
          }
          : {
            answers: {},
            remainingSeconds: fullDuration,
            currentPage: 1,
            startTime: Date.now(),
            endTime: null,
            pauseId: initialPauseId,
            boundUid: null,
            submittedResult: null,
            frozen: false,
          };

        setAnswers(snapshot.current.answers);

        setRemainingSeconds(
          snapshot.current.remainingSeconds
        );

        setCurrentPage(
          snapshot.current.currentPage
        );

        if (snapshot.current.submittedResult) {
          setSubmitted(true);

          setSubmittedResult(
            snapshot.current.submittedResult
          );

          setResultModalOpen(true);
        }

        setReady(true);
      } catch (error) {
        if (!cancelled) {
          setRestoreError(
            error.message ||
            "Unable to restore this Topic Wise attempt."
          );
        }
      }
    }

    restore();

    return () => {
      cancelled = true;
    };
  }, [
    id,
    uid,
    cid,
    draftKey,
    mode,
    initialPauseId,
    fullDuration,
    totalPages,
    questions,
    questionIds,
    guestAction,
    isHandoff,
    governmentExamsSlug,
  ]);

  /* SAVE PAUSE / FINISH */

  async function save(action) {
    if (
      !ready ||
      restoreError ||
      lock.current
    ) {
      return false;
    }

    if (snapshot.current.submittedResult) {
      setResultModalOpen(true);
      return true;
    }

    lock.current = true;
    snapshot.current.frozen = true;

    setSaving(true);
    setSaveError("");

    if (action === "submit") {
      snapshot.current.endTime ??= Date.now();
    }

    try {
      if (!positiveId(uid)) {
        checkpoint(action);

        window.location.assign(
          `/login?redirect=${encodeURIComponent(
            guestExamLoginRedirectPath(action)
          )}`
        );

        return false;
      }

      const current = snapshot.current;

      const payload = {
        cid,
        exam_id: id,
        exam_type: type,
        lastposition: type,

        total_questions: totalQuestions,

        total_mark:
          Number(exam?.total_mark) || totalQuestions,

        remaining_seconds:
          current.remainingSeconds,

        start_time:
          current.startTime,

        ...(action === "submit"
          ? { end_time: current.endTime }
          : {}),

        answer_array: answerKeys,

        user_answers:
          questions.map(
            (q) =>
              current.answers[String(q.id)] ?? 0
          ),

        __scoring: {
          markPerCorrect: 1,
          negativeMarkPerWrong: 0.333,
        },
      };

      const isResuming = Boolean(current.pauseId);
      const result = await post(
        "/api/topicwise-attempt",
        {
          ...payload,
          action: isResuming ? "update" : "create",
          exam_status:
            action === "submit"
              ? "finish"
              : "pause",
          ...(isResuming
            ? { pauseid: current.pauseId }
            : {}),
        }
      );

      if (!isResuming) {
        const createdId = positiveId(
          getAttemptId(result)
        );

        if (!createdId) {
          throw new Error(
            "The backend did not return the created attempt ID. Contact support before retrying."
          );
        }

        current.pauseId = createdId;
        current.boundUid = Number(uid);

        if (action !== "submit") storeDraft();
        if (isHandoff) checkpoint(action);
      }

      if (action === "submit") {
        const finalResult = {
          ...result.savedResult,
          id: current.pauseId,
          pauseid: current.pauseId,
          exam_id: id,
          exam_type: type,

          exam_name:
            exam?.exam_name ??
            exam?.title ??
            "",
        };

        current.submittedResult = finalResult;

        setSubmittedResult(finalResult);
        setSubmitted(true);
        setResultModalOpen(true);

        try {
          localStorage.removeItem(draftKey);
        } catch { }

        if (isHandoff) {
          try {
            checkpoint(action);
          } catch { }
        }
      } else {
        setPaused(true);
        setHandoffConsumed(true);

        storeDraft();

        if (isHandoff) {
          try {
            clearGuestExamHandoff();
          } catch { }
        }

        const url = new URL(window.location.href);

        url.searchParams.delete("guestAction");

        window.history.replaceState(
          window.history.state,
          "",
          url.pathname + url.search + url.hash
        );
      }

      return true;
    } catch (error) {
      if (error.status === 401) {
        try {
          checkpoint(action);

          window.location.assign(
            `/login?redirect=${encodeURIComponent(
              guestExamLoginRedirectPath(action)
            )}`
          );
        } catch (failure) {
          setSaveError(failure.message);
        }
      } else {
        setSaveError(
          error.message ||
          "Unable to save. Your answers are retained; retry Finish."
        );
      }

      return false;
    } finally {
      lock.current = false;
      setSaving(false);
    }
  }

  /* APPLY GUEST ACTION AFTER LOGIN */

  useEffect(() => {
    if (
      !ready ||
      restoreError ||
      !isHandoff ||
      autoHandled.current
    ) {
      return;
    }

    autoHandled.current = true;

    if (!snapshot.current.submittedResult) {
      void save(guestAction);
    }
  }, [
    ready,
    restoreError,
    isHandoff,
    guestAction,
  ]);

  /* TIMER */

  useEffect(() => {
    if (
      !ready ||
      restoreError ||
      fullDuration <= 0 ||
      submitted ||
      paused ||
      saving ||
      snapshot.current.frozen ||
      remainingSeconds <= 0
    ) {
      return;
    }

    let lastTick = Date.now();

    const timer = window.setInterval(() => {
      if (
        snapshot.current.frozen ||
        lock.current
      ) {
        return;
      }

      const elapsed = Math.floor(
        (Date.now() - lastTick) / 1000
      );

      if (elapsed < 1) return;

      lastTick += elapsed * 1000;

      snapshot.current.remainingSeconds = Math.max(
        0,
        snapshot.current.remainingSeconds - elapsed
      );

      setRemainingSeconds(
        snapshot.current.remainingSeconds
      );

      storeDraft();
    }, 250);

    return () => window.clearInterval(timer);
  }, [
    ready,
    restoreError,
    submitted,
    paused,
    saving,
    remainingSeconds,
    draftKey,
  ]);

  useEffect(() => {
    if (
      !ready ||
      restoreError ||
      (isHandoff && !handoffConsumed) ||
      fullDuration <= 0 ||
      saving ||
      submitted ||
      paused ||
      remainingSeconds !== 0 ||
      timeoutHandled.current
    ) {
      return;
    }

    timeoutHandled.current = true;
    void save("submit");
  }, [
    ready,
    restoreError,
    isHandoff,
    handoffConsumed,
    saving,
    submitted,
    paused,
    remainingSeconds,
  ]);

  function handleAnswer(questionId, value) {
    if (
      !ready ||
      saving ||
      paused ||
      submitted ||
      snapshot.current.frozen ||
      (
        fullDuration > 0 &&
        snapshot.current.remainingSeconds <= 0
      )
    ) {
      return;
    }

    snapshot.current.answers = {
      ...snapshot.current.answers,
      [String(questionId)]: value,
    };

    setAnswers(snapshot.current.answers);
    storeDraft();
  }

  function handlePageChange(page) {
    if (!ready || saving) return;

    const next = Math.max(
      1,
      Math.min(
        totalPages,
        Number(page) || 1
      )
    );

    snapshot.current.currentPage = next;

    setCurrentPage(next);
    storeDraft();

    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  }

  function handlePause() {
    if (
      paused &&
      !saving &&
      !submitted &&
      (
        fullDuration === 0 ||
        snapshot.current.remainingSeconds > 0
      )
    ) {
      snapshot.current.frozen = false;
      snapshot.current.endTime = null;

      setPaused(false);
      setSaveError("");
      return;
    }

    void save("pause");
  }

  function viewAttempted() {
    try {
      clearGuestExamHandoff();
    } catch { }

    router.push(
      `/dashboard/${encodeURIComponent(
        governmentExamsSlug
      )}/exam-attempted`
    );
  }

  if (restoreError) {
    return (
      <p
        role="alert"
        className="rounded-xl bg-red-50 p-5 text-red-700"
      >
        {restoreError}
      </p>
    );
  }

  if (!ready) {
    return (
      <p role="status" className="p-6">
        Restoring your Topic Wise exam…
      </p>
    );
  }

  const startIndex =
    (currentPage - 1) * pageSize;

  return (
    <main className="min-h-screen bg-[#f5f9ff] py-6">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
          <Link
            href={`${basePath}/test/${slug}/${examSlug}`}
            className="font-bold text-blue-700"
          >
            Back to Instructions
          </Link>

          <p className="rounded-xl bg-white px-4 py-3 font-black text-[#071f55]">
            {durationMinutes > 0
              ? `${Math.floor(remainingSeconds / 60)}:${String(
                remainingSeconds % 60
              ).padStart(2, "0")}`
              : "Untimed practice"}
          </p>
        </div>

        <ExamHero
          exam={exam}
          questionsCount={totalQuestions}
          timeLeft={remainingSeconds}
          durationMinutes={durationMinutes}
        />

        <ExamProgress
          answeredCount={stats.attempted}
          totalQuestions={totalQuestions}
          currentPage={currentPage}
          totalPages={totalPages}
        />

        {saveError && (
          <p
            role="alert"
            className="mt-5 rounded-xl bg-red-50 p-4 text-red-700"
          >
            {saveError}
          </p>
        )}

        {paused && (
          <p
            role="status"
            className="mt-5 rounded-xl bg-amber-50 p-4"
          >
            Exam paused. Select Resume to continue.
          </p>
        )}

        {submitted && (
          <p
            role="status"
            className="mt-5 rounded-xl bg-green-50 p-4 text-green-900"
          >
            Exam saved. Correct:{" "}
            {submittedResult?.total_correct}
            {" · "}Wrong:{" "}
            {submittedResult?.total_wrong}
            {" · "}Score:{" "}
            {submittedResult?.user_score}
          </p>
        )}

        <ExamQuestions
          questions={questions.slice(
            startIndex,
            startIndex + pageSize
          )}
          currentPage={currentPage}
          answers={answers}
          onAnswer={handleAnswer}
          disabled={
            saving ||
            submitted ||
            paused ||
            snapshot.current.frozen ||
            (
              fullDuration > 0 &&
              remainingSeconds <= 0
            )
          }
          imagePath={imagePath}
        />

        <ExamPagination
          currentPage={currentPage}
          totalPages={totalPages}
          onPrevious={() =>
            handlePageChange(currentPage - 1)
          }
          onNext={() =>
            handlePageChange(currentPage + 1)
          }
          onPageChange={handlePageChange}
        />

        {!submitted && (
          <ExamControls
            submitted={submitted}
            paused={paused}
            saving={saving}
            onPause={handlePause}
            onFinish={() => save("submit")}
          />
        )}

        {submitted && (
          <button
            type="button"
            onClick={() => setResultModalOpen(true)}
            className="mt-5 rounded-xl bg-blue-700 px-5 py-3 font-bold text-white"
          >
            Show Result
          </button>
        )}
      </div>

      <ExamResultModal
        open={resultModalOpen}
        result={submittedResult}
        examTitle={
          exam?.exam_name ??
          exam?.title ??
          "Topic Wise Exam"
        }
        onClose={() => setResultModalOpen(false)}
        onViewAnalysis={viewAttempted}
      />
    </main>
  );
}

"use client";

import {
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import { useRouter } from "next/navigation";

import {
  saveGuestExamHandoff,
} from "@/lib/guestExamHandoff";

import ExamTopBar from "./ExamTopBar";
import ExamHero from "./ExamHero";
import ExamProgress from "./ExamProgress";
import ExamQuestions from "./ExamQuestions";
import ExamPagination from "./ExamPagination";
import ExamControls from "./ExamControls";
import LoginRequiredModal from "./LoginRequiredModal";

const QUESTIONS_PER_PAGE = 10;

function positiveId(value) {
  const number = Number(value);

  return Number.isSafeInteger(number) && number > 0
    ? number
    : null;
}

export default function ExamClient({
  exam,
  questions = [],
  imagePath = "",
  uid = 0,
  cid,
  slug = "",
  examSlug = "",
  governmentExamsSlug = "",
  examName = "Kerala PSC",
  examId,
  examTitle = "",
}) {
  const router = useRouter();

  const selectedExamId = positiveId(examId ?? exam?.id);

  const durationMinutes = Math.max(
    0,
    Number(exam?.total_minutes) || 0
  );

  const durationSeconds = Math.floor(
    durationMinutes * 60
  );

  const totalPages = Math.max(
    1,
    Math.ceil(questions.length / QUESTIONS_PER_PAGE)
  );

  const [currentPage, setCurrentPage] = useState(1);
  const [answers, setAnswers] = useState({});
  const [timeLeft, setTimeLeft] = useState(durationSeconds);
  const [handoffError, setHandoffError] = useState("");
  const [redirecting, setRedirecting] = useState(false);

  const [modalState, setModalState] = useState({
    open: false,
    action: "",
  });

  const clock = useRef(null);
  const answerSnapshot = useRef({});
  const pendingAttempt = useRef(null);
  const navigationLock = useRef(false);

  const questionIds = useMemo(
    () => questions.map((question) => String(question.id)),
    [questions]
  );

  /*
   * Start the timer after mounting.
   * The deadline measures actual elapsed time.
   */
  useEffect(() => {
    const startTime = Date.now();

    clock.current = {
      startTime,
      deadline:
        durationSeconds > 0
          ? startTime + durationSeconds * 1000
          : null,
    };

    setTimeLeft(durationSeconds);
  }, [selectedExamId, durationSeconds]);

  /*
   * Freeze the clock while an attempt is awaiting login.
   */
  useEffect(() => {
    if (
      durationSeconds <= 0 ||
      modalState.open ||
      redirecting
    ) {
      return;
    }

    function tick() {
      const deadline = clock.current?.deadline;

      if (!deadline) return;

      setTimeLeft(
        Math.max(
          0,
          Math.ceil((deadline - Date.now()) / 1000)
        )
      );
    }

    tick();

    const timer = window.setInterval(tick, 250);

    return () => window.clearInterval(timer);
  }, [durationSeconds, modalState.open, redirecting]);

  const currentQuestions = useMemo(() => {
    const start =
      (currentPage - 1) * QUESTIONS_PER_PAGE;

    return questions.slice(
      start,
      start + QUESTIONS_PER_PAGE
    );
  }, [questions, currentPage]);

  const answeredCount = questions.reduce(
    (count, question) => {
      const answer = answers[String(question.id)];

      const answered =
        answer != null &&
        String(answer).trim() !== "" &&
        String(answer).trim() !== "0";

      return count + (answered ? 1 : 0);
    },
    0
  );

  const isTimeOver =
    durationSeconds > 0 && timeLeft <= 0;

  function remainingAt(now) {
    if (durationSeconds <= 0) return 0;

    return Math.max(
      0,
      Math.ceil(
        ((clock.current?.deadline ?? now) - now) / 1000
      )
    );
  }

  function handleAnswer(questionId, answer) {
    if (
      modalState.open ||
      redirecting ||
      pendingAttempt.current ||
      (
        durationSeconds > 0 &&
        remainingAt(Date.now()) <= 0
      )
    ) {
      return;
    }

    const nextAnswers = {
      ...answerSnapshot.current,
      [String(questionId)]: answer,
    };

    answerSnapshot.current = nextAnswers;
    setAnswers(nextAnswers);
  }

  function handlePageChange(page) {
    if (redirecting) return;

    const nextPage = Math.max(
      1,
      Math.min(totalPages, Number(page) || 1)
    );

    setCurrentPage(nextPage);

    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  }

  /*
   * Capture answers and the finish time when Finish is clicked,
   * before the user spends time logging in.
   */
  function captureAttempt(action) {
    const courseId = positiveId(cid);

    if (
      !courseId ||
      !selectedExamId ||
      !governmentExamsSlug ||
      !slug ||
      !examSlug
    ) {
      throw new Error(
        "Exam information is incomplete. Please reopen this exam."
      );
    }

    if (
      !questions.length ||
      questions.some((question) => question.id == null) ||
      new Set(questionIds).size !== questionIds.length
    ) {
      throw new Error(
        "The question paper is incomplete or contains duplicate question IDs."
      );
    }

    if (!clock.current?.startTime) {
      throw new Error(
        "The exam is still loading. Please try again."
      );
    }

    const now = Date.now();
    const remainingSeconds = remainingAt(now);

    setTimeLeft(remainingSeconds);

    return {
      examId: selectedExamId,
      examType: "twe",
      cid: courseId,
      governmentExamsSlug,

      slug,
      topicSlug: slug,
      examSlug,

      action,
      answers: { ...answerSnapshot.current },
      questionIds: [...questionIds],
      currentPage,

      remainingSeconds,
      startTime: clock.current.startTime,
      endTime: action === "submit" ? now : null,

      pauseId: null,
      boundUid: null,
      submittedResult: null,
      frozen: true,

      examTitle:
        examTitle ||
        exam?.exam_name ||
        exam?.title ||
        "Topic Wise Exam",
    };
  }

  function continueAttempt(attempt) {
    if (navigationLock.current) return;

    navigationLock.current = true;
    setHandoffError("");

    try {
      saveGuestExamHandoff(attempt);

      const destination =
        `/dashboard/${encodeURIComponent(governmentExamsSlug)}` +
        `/topic-wise-exams/test/${encodeURIComponent(slug)}` +
        `/${encodeURIComponent(examSlug)}/start` +
        `?guestAction=${attempt.action}`;

      setRedirecting(true);

      if (positiveId(uid)) {
        router.push(destination);
      } else {
        router.push(
          `/login?redirect=${encodeURIComponent(destination)}`
        );
      }
    } catch (error) {
      navigationLock.current = false;
      setRedirecting(false);

      setHandoffError(
        error?.message ||
        "Unable to retain your answers. Please retry."
      );
    }
  }

  function requestAction(action) {
    if (redirecting || modalState.open) return;

    setHandoffError("");

    try {
      const attempt = captureAttempt(action);
      pendingAttempt.current = attempt;

      setModalState({
        open: true,
        action: action === "pause" ? "pause" : "finish",
      });

      // A signed-in user can continue without another login.
      if (positiveId(uid)) {
        continueAttempt(attempt);
      }
    } catch (error) {
      setHandoffError(
        error?.message || "Unable to prepare this attempt."
      );
    }
  }

  function handleLogin() {
    const attempt = pendingAttempt.current;

    if (!attempt) {
      setHandoffError(
        "Please close this dialog and select Finish again."
      );
      return;
    }

    continueAttempt(attempt);
  }

  function handleCloseModal() {
    if (redirecting) return;

    const attempt = pendingAttempt.current;

    if (clock.current && durationSeconds > 0 && attempt) {
      clock.current.deadline =
        Date.now() + attempt.remainingSeconds * 1000;

      setTimeLeft(attempt.remainingSeconds);
    }

    pendingAttempt.current = null;
    navigationLock.current = false;

    setHandoffError("");

    setModalState({
      open: false,
      action: "",
    });
  }

  const disabled =
    isTimeOver || modalState.open || redirecting;

  return (
    <>
      <main className="min-h-screen bg-[#f5f9ff]">
        <div className="mx-auto mt-20 w-full max-w-7xl px-4 py-6 sm:px-6 lg:px-8 lg:py-8">
          <ExamTopBar
            slug={slug}
            examSlug={examSlug}
            governmentExamsSlug={governmentExamsSlug}
            examId={selectedExamId}
            examTitle={
              examTitle || exam?.exam_name || ""
            }
            timeLeft={timeLeft}
            durationMinutes={durationMinutes}
          />

          <ExamHero
            exam={exam}
            questionsCount={questions.length}
            timeLeft={timeLeft}
            durationMinutes={durationMinutes}
            examName={examName}
          />

          <ExamProgress
            answeredCount={answeredCount}
            totalQuestions={questions.length}
            currentPage={currentPage}
            totalPages={totalPages}
          />

          {durationSeconds <= 0 && (
            <p className="mt-5 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm font-semibold text-amber-700">
              Untimed practice. No exam duration was
              received from the API.
            </p>
          )}

          {isTimeOver && (
            <div className="mt-5 rounded-2xl border border-red-200 bg-red-50 p-4">
              <p className="font-black text-red-700">
                Time is over
              </p>

              <p className="mt-1 text-sm text-red-600">
                Your answers are locked. Select Finish
                to save your attempt.
              </p>
            </div>
          )}

          {handoffError && (
            <p
              role="alert"
              className="mt-5 rounded-xl bg-red-50 p-4 text-sm text-red-700"
            >
              {handoffError}
            </p>
          )}

          {redirecting && (
            <p
              role="status"
              className="mt-5 rounded-xl bg-blue-50 p-4 text-sm text-blue-700"
            >
              Continuing with your saved answers…
            </p>
          )}

          <ExamQuestions
            questions={currentQuestions}
            currentPage={currentPage}
            answers={answers}
            onAnswer={handleAnswer}
            disabled={disabled}
            imagePath={imagePath}
          />

          <ExamPagination
            currentPage={currentPage}
            totalPages={totalPages}
            onPrevious={() =>
              handlePageChange(currentPage - 1)
            }
            onNext={() =>
              handlePageChange(currentPage + 1)
            }
            onPageChange={handlePageChange}
          />

          {!redirecting && (
            <ExamControls
              onPause={() => requestAction("pause")}
              onFinish={() => requestAction("submit")}
            />
          )}

          {redirecting && positiveId(uid) && (
            <button
              type="button"
              onClick={() => window.location.reload()}
              className="mt-4 rounded-xl border border-blue-200 px-4 py-2 text-sm font-bold text-blue-700"
            >
              Reload if navigation does not complete
            </button>
          )}

          {!redirecting &&
            modalState.open &&
            positiveId(uid) &&
            handoffError && (
              <div className="mt-4 flex gap-3">
                <button
                  type="button"
                  onClick={handleLogin}
                  className="rounded-xl bg-blue-700 px-4 py-2 font-bold text-white"
                >
                  Retry
                </button>

                <button
                  type="button"
                  onClick={handleCloseModal}
                  className="rounded-xl border px-4 py-2 font-bold"
                >
                  Cancel
                </button>
              </div>
            )}
        </div>
      </main>

      {!positiveId(uid) && (
        <LoginRequiredModal
  open={modalState.open}
  action={modalState.action}
  onClose={handleCloseModal}
  onLogin={handleLogin}
  error={handoffError}
/>
      )}
    </>
  );
}

