"use client";

import {
  useEffect,
  useMemo,
  useState,
} from "react";

import {
  ChevronLeft,
  ChevronRight,
} from "lucide-react";

import QuestionResultCard from "./QuestionResultCard";

const QUESTIONS_PER_PAGE = 10;

/* =========================================================
   QUESTION ANALYSIS LIST
========================================================= */

export default function QuestionAnalysisList({
  rows = [],
  loading = false,
}) {
  const [currentPage, setCurrentPage] = useState(1);

  const safeRows = Array.isArray(rows) ? rows : [];

  const totalPages = Math.max(
    1,
    Math.ceil(safeRows.length / QUESTIONS_PER_PAGE)
  );

  useEffect(() => {
    setCurrentPage(1);
  }, [rows]);

  const safePage = Math.min(currentPage, totalPages);

  const paginatedRows = useMemo(() => {
    const start = (safePage - 1) * QUESTIONS_PER_PAGE;

    return safeRows.slice(
      start,
      start + QUESTIONS_PER_PAGE
    );
  }, [rows, safePage]);

  const startQuestion = safeRows.length
    ? (safePage - 1) * QUESTIONS_PER_PAGE + 1
    : 0;

  const endQuestion = Math.min(
    safePage * QUESTIONS_PER_PAGE,
    safeRows.length
  );

  function goToPage(page) {
    const nextPage = Math.min(
      Math.max(page, 1),
      totalPages
    );

    setCurrentPage(nextPage);

    window.requestAnimationFrame(() => {
      document
        .getElementById("question-analysis")
        ?.scrollIntoView({
          behavior: "smooth",
          block: "start",
        });
    });
  }

  if (loading) {
    return (
      <section
        id="question-analysis"
        className="scroll-mt-24 space-y-4"
      >
        <SectionHeader />

        {Array.from({ length: 4 }, (_, index) => (
          <div
            key={index}
            className="
              h-44 animate-pulse rounded-[22px]
              border border-slate-200 bg-white
            "
          />
        ))}
      </section>
    );
  }

  if (!safeRows.length) {
    return (
      <section
        id="question-analysis"
        className="scroll-mt-24 space-y-4"
      >
        <SectionHeader />

        <div
          className="
            rounded-[22px] border border-slate-200
            bg-white px-6 py-12 text-center
            text-sm font-semibold text-slate-500
          "
        >
          Questions are not available for this exam attempt.
        </div>
      </section>
    );
  }

  return (
    <section
      id="question-analysis"
      className="scroll-mt-24 space-y-5"
    >
      {/* HEADER */}

      <div
        className="
          flex flex-col gap-4
          sm:flex-row sm:items-end sm:justify-between
        "
      >
        <SectionHeader />

        <div
          className="
            w-fit rounded-full border border-slate-200
            bg-white px-4 py-2
            text-xs font-bold text-slate-500
          "
        >
          Showing{" "}
          <span className="text-[#017dc0]">
            {startQuestion}
          </span>
          {" - "}
          <span className="text-[#017dc0]">
            {endQuestion}
          </span>
          {" of "}
          <span className="text-[#082e5a]">
            {safeRows.length}
          </span>
        </div>
      </div>

      {/* QUESTION + YOUR ANSWER + CORRECT ANSWER */}

      <div className="space-y-4">
        {paginatedRows.map((row, index) => {
          const actualIndex =
            (safePage - 1) * QUESTIONS_PER_PAGE + index;

          return (
            <QuestionResultCard
              key={`${row?.id ?? "question"}-${actualIndex}`}
              row={{
                ...row,
                number: actualIndex + 1,
              }}
            />
          );
        })}
      </div>

      {/* PAGINATION */}

      {totalPages > 1 && (
        <Pagination
          currentPage={safePage}
          totalPages={totalPages}
          onPageChange={goToPage}
        />
      )}
    </section>
  );
}

/* =========================================================
   SECTION HEADER
========================================================= */

function SectionHeader() {
  return (
    <div>
      <p
        className="
          text-[10px] font-extrabold uppercase
          tracking-[0.18em] text-[#017dc0]
        "
      >
        Exam Analytics
      </p>

      <h2
        className="
          mt-1 text-2xl font-black tracking-tight
          text-[#082e5a] sm:text-[27px]
        "
      >
        Questions & Answers
      </h2>

      <p className="mt-1 text-sm text-slate-500">
        Review your answer and the correct answer
        for each question.
      </p>
    </div>
  );
}

/* =========================================================
   PAGINATION
========================================================= */

function Pagination({
  currentPage,
  totalPages,
  onPageChange,
}) {
  const pages = getPageNumbers({
    currentPage,
    totalPages,
  });

  return (
    <div
      className="
        flex flex-col gap-4 rounded-[20px]
        border border-slate-200 bg-white
        px-4 py-4
        sm:flex-row sm:items-center sm:justify-between
      "
    >
      <p className="text-xs font-bold text-slate-500">
        Page{" "}
        <span className="text-[#082e5a]">
          {currentPage}
        </span>
        {" of "}
        <span className="text-[#082e5a]">
          {totalPages}
        </span>
      </p>

      <div className="flex flex-wrap items-center gap-2">
        <button
          type="button"
          disabled={currentPage === 1}
          onClick={() => onPageChange(currentPage - 1)}
          className="
            inline-flex h-10 items-center gap-1
            rounded-xl border border-slate-200
            px-3 text-xs font-bold text-slate-600
            hover:border-[#017dc0] hover:text-[#017dc0]
            disabled:cursor-not-allowed disabled:opacity-40
          "
        >
          <ChevronLeft size={15} />
          Previous
        </button>

        {pages.map((page, index) =>
          page === "..." ? (
            <span
              key={`dots-${index}`}
              className="
                flex h-10 w-8 items-center justify-center
                text-xs text-slate-400
              "
            >
              ...
            </span>
          ) : (
            <button
              key={page}
              type="button"
              onClick={() => onPageChange(page)}
              aria-current={
                page === currentPage ? "page" : undefined
              }
              className={`
                h-10 min-w-10 rounded-xl px-3
                text-xs font-extrabold transition
                ${page === currentPage
                  ? "bg-gradient-to-r from-[#164fa5] to-[#017dc0] text-white"
                  : "border border-slate-200 bg-white text-slate-600 hover:border-[#017dc0]"
                }
              `}
            >
              {page}
            </button>
          )
        )}

        <button
          type="button"
          disabled={currentPage === totalPages}
          onClick={() => onPageChange(currentPage + 1)}
          className="
            inline-flex h-10 items-center gap-1
            rounded-xl border border-slate-200
            px-3 text-xs font-bold text-slate-600
            hover:border-[#017dc0] hover:text-[#017dc0]
            disabled:cursor-not-allowed disabled:opacity-40
          "
        >
          Next
          <ChevronRight size={15} />
        </button>
      </div>
    </div>
  );
}

/* =========================================================
   PAGE NUMBERS
========================================================= */

function getPageNumbers({
  currentPage,
  totalPages,
}) {
  if (totalPages <= 7) {
    return Array.from(
      { length: totalPages },
      (_, index) => index + 1
    );
  }

  if (currentPage <= 4) {
    return [1, 2, 3, 4, 5, "...", totalPages];
  }

  if (currentPage >= totalPages - 3) {
    return [
      1,
      "...",
      totalPages - 4,
      totalPages - 3,
      totalPages - 2,
      totalPages - 1,
      totalPages,
    ];
  }

  return [
    1,
    "...",
    currentPage - 1,
    currentPage,
    currentPage + 1,
    "...",
    totalPages,
  ];
}

"use client";

import {
    useCallback,
    useEffect,
    useRef,
    useState,
} from "react";

import { useRouter } from "next/navigation";

import {
    calculateMockResult,
    getAttemptId,
    getDatabaseResult,
    getExamTotalMark,
    postJson,
} from "../utils/mockTestUtils";

import {
    buildMockAttemptPayload,
    getMockExamTitle,
} from "../utils/mockAttemptUtils";

import {
    clearGuestExamHandoff,
} from "@/lib/guestExamHandoff";

export default function useMockExamAttempt({
    uid,
    cid,
    examId,
    examType = "mock",
    exam,
    questions = [],
    answersRef,
    remainingSeconds,
    currentPage,
    initialPauseId = null,
    startTime = 0,
    examTitle = "",
    governmentExamsSlug = "",
    guestAction = "",
    stopTimer,
    onSavingChange,
    onSubmittedChange,
    onPausedChange,
}) {
    const router = useRouter();

    /* =========================================
       REFS
    ========================================= */

    const requestRef = useRef(false);
    const timeoutHandledRef = useRef(false);

    /* =========================================
       STATE
    ========================================= */

    const [saving, setSaving] = useState(false);
    const [submitted, setSubmitted] = useState(false);

    const [pauseId, setPauseId] = useState(
        initialPauseId || null
    );

    const [isPaused, setIsPaused] = useState(false);

    const [saveMessage, setSaveMessage] = useState("");
    const [saveError, setSaveError] = useState("");

    const [resultModalOpen, setResultModalOpen] =
        useState(false);

    const [submittedResult, setSubmittedResult] =
        useState(null);

    const [resultLoading, setResultLoading] =
        useState(false);

    /* =========================================
       UPDATE STATES
    ========================================= */

    const updateSaving = useCallback(
        (value) => {
            setSaving(value);
            onSavingChange?.(value);
        },
        [onSavingChange]
    );

    const updateSubmitted = useCallback(
        (value) => {
            setSubmitted(value);
            onSubmittedChange?.(value);
        },
        [onSubmittedChange]
    );

    const updatePaused = useCallback(
        (value) => {
            setIsPaused(value);
            onPausedChange?.(value);
        },
        [onPausedChange]
    );

    /* =========================================
       CALCULATE RESULT
    ========================================= */

    const getCurrentResult = useCallback(
        () =>
            calculateMockResult({
                questions,
                answers: answersRef?.current || {},
            }),
        [questions, answersRef]
    );

    /* =========================================
       BUILD ATTEMPT PAYLOAD
    ========================================= */

    const buildPayload = useCallback(
        ({
            examStatus,
            result,
            completedAt,
        }) =>
            buildMockAttemptPayload({
                cid,
                examId,
                examType,
                exam,
                questions,
                answers: answersRef?.current || {},
                remainingSeconds,
                startTime,
                completedAt,
                examStatus,
                result,
            }),
        [
            cid,
            examId,
            examType,
            exam,
            questions,
            answersRef,
            remainingSeconds,
            startTime,
        ]
    );

    /* =========================================
       FETCH SAVED RESULT
    ========================================= */

    const fetchDatabaseResult = useCallback(
        async (savedAttemptId) => {
            setResultLoading(true);

            try {
                const response = await postJson(
                    "/api/exam-attempt/analytics-details",
                    {
                        cid,
                        id: savedAttemptId,
                        exam_type: examType,
                    }
                );

                const databaseResult =
                    getDatabaseResult(response);

                if (!databaseResult) {
                    throw new Error(
                        "Saved result was not returned."
                    );
                }

                return databaseResult;
            } finally {
                setResultLoading(false);
            }
        },
        [cid, examType]
    );

    /* =========================================
       SAVE PAUSE
    ========================================= */

    const savePause = useCallback(async () => {
        if (
            requestRef.current ||
            submitted ||
            remainingSeconds <= 0
        ) {
            return;
        }

        requestRef.current = true;
        updateSaving(true);

        setSaveError("");
        setSaveMessage("");

        try {
            const payload = buildPayload({
                examStatus: "pause",
            });

            let savedPauseId = pauseId;

            if (savedPauseId) {
                await postJson(
                    "/api/exam-attempt/update",
                    {
                        ...payload,
                        pauseid: String(savedPauseId),
                    }
                );
            } else {
                const created = await postJson(
                    "/api/exam-attempt/create",
                    payload
                );

                savedPauseId = getAttemptId(created);

                if (!savedPauseId) {
                    throw new Error(
                        "Pause ID was not returned."
                    );
                }

                setPauseId(savedPauseId);
            }

            try {
                localStorage.setItem(
                    `exam_draft_${uid}_${cid}_${examType}_${examId}`,
                    JSON.stringify({
                        pauseId: savedPauseId,
                        answers: answersRef?.current || {},
                        remainingSeconds,
                        currentPage,
                    })
                );
            } catch (storageError) {
                console.warn(
                    "Unable to save local exam draft:",
                    storageError
                );
            }

            updatePaused(true);
            clearGuestExamHandoff();

            setSaveMessage(
                "Exam paused successfully."
            );
        } catch (error) {
            console.error(
                "PAUSE MOCK TEST:",
                error
            );

            setSaveError(
                error?.message ||
                "Unable to pause exam."
            );
        } finally {
            requestRef.current = false;
            updateSaving(false);
        }
    }, [
        submitted,
        remainingSeconds,
        getCurrentResult,
        buildPayload,
        pauseId,
        answersRef,
        uid,
        cid,
        examType,
        examId,
        currentPage,
        updatePaused,
        updateSaving,
    ]);

    /* =========================================
       FINISH EXAM
    ========================================= */

    const finishExam = useCallback(
        async ({ timeout = false } = {}) => {
            if (
                requestRef.current ||
                submitted
            ) {
                return;
            }

            requestRef.current = true;
            updateSaving(true);

            setSaveError("");
            setSaveMessage("");

            try {
                /* =================================
                   CALCULATE SCORE
                ================================= */

                const calculated =
                    getCurrentResult();

                /* =================================
                   GET OR CREATE ATTEMPT ID
                ================================= */

                const finalPayload =
                    buildPayload({
                        examStatus: "finish",
                        result: calculated,
                        completedAt: Date.now(),
                    });

                let finalPauseId = pauseId;

                if (finalPauseId) {
                    await postJson(
                        "/api/exam-attempt/update",
                        {
                            ...finalPayload,
                            pauseid: String(finalPauseId),
                        }
                    );
                } else {
                    const createResult =
                        await postJson(
                            "/api/exam-attempt/create",
                            finalPayload
                        );

                    finalPauseId =
                        getAttemptId(createResult);

                    if (!finalPauseId) {
                        throw new Error(
                            "Saved attempt ID was not returned."
                        );
                    }

                    setPauseId(finalPauseId);
                }

                /* =================================
                   SUBMISSION SUCCESSFUL
                ================================= */

                updateSubmitted(true);
                updatePaused(false);

                stopTimer?.();

                try {
                    clearGuestExamHandoff();
                } catch (storageError) {
                    console.warn(
                        "Unable to clear guest handoff:",
                        storageError
                    );
                }

                try {
                    localStorage.removeItem(
                        `exam_draft_${uid}_${cid}_${examType}_${examId}`
                    );
                } catch (storageError) {
                    console.warn(
                        "Unable to clear exam draft:",
                        storageError
                    );
                }

                /* =================================
                   LOCAL RESULT
                ================================= */

                const localResult = {
                    id: finalPauseId,
                    pauseid: finalPauseId,
                    exam_id: examId,
                    exam_type: examType,
                    exam_status: "finish",

                    exam_name: getMockExamTitle({
                        exam,
                        fallback: examTitle,
                    }),

                    total_questions: questions.length,

                    total_mark: getExamTotalMark(
                        exam,
                        questions.length
                    ),

                    answer_array:
                        calculated.answerArray,

                    user_answers:
                        calculated.userAnswers,

                    total_attempted:
                        calculated.totalAttempted,

                    total_correct:
                        calculated.totalCorrect,

                    total_wrong:
                        calculated.totalWrong,

                    user_score:
                        calculated.userScore,

                    minus_mark:
                        calculated.minusMark,
                };

                /* =================================
                   GET DATABASE RESULT
                ================================= */

                let resultForModal = localResult;
                let resultDetailsLoaded = true;

                try {
                    const databaseResult =
                        await fetchDatabaseResult(
                            finalPauseId
                        );

                    resultForModal = {
                        ...databaseResult,
                        // Keep counts and score calculated from this submission;
                        // older analytics rows may contain empty result fields.
                        ...localResult,

                        // Preserve the actual saved
                        // attempt ID for navigation.
                        id: finalPauseId,
                        pauseid: finalPauseId,
                    };
                } catch (resultError) {
                    console.error(
                        "RESULT DETAILS ERROR:",
                        resultError
                    );

                    resultDetailsLoaded = false;

                    setSaveMessage(
                        "Exam submitted. Showing the calculated result; saved analytics details are unavailable."
                    );
                }

                /* =================================
                   SHOW RESULT MODAL
                ================================= */

                setSubmittedResult(resultForModal);

                if (resultDetailsLoaded) {
                    setSaveMessage(
                        timeout
                            ? "Time is over. Exam submitted automatically."
                            : "Exam submitted successfully."
                    );
                }

                setResultModalOpen(true);
            } catch (error) {
                console.error(
                    "FINISH MOCK TEST:",
                    error
                );

                if (timeout) {
                    timeoutHandledRef.current = false;
                }

                setSaveError(
                    error?.message ||
                    "Unable to submit exam."
                );
            } finally {
                requestRef.current = false;
                updateSaving(false);
            }
        },
        [
            submitted,
            getCurrentResult,
            pauseId,
            buildPayload,
            fetchDatabaseResult,
            stopTimer,
            exam,
            examId,
            examTitle,
            examType,
            questions.length,
            uid,
            cid,
            updatePaused,
            updateSaving,
            updateSubmitted,
        ]
    );

    /* =========================================
       AUTO SUBMIT WHEN TIMER ENDS
    ========================================= */

    useEffect(() => {
        if (
            remainingSeconds !== 0 ||
            submitted ||
            saving ||
            isPaused ||
            timeoutHandledRef.current
        ) {
            return;
        }

        if (!exam || !questions.length) {
            return;
        }

        timeoutHandledRef.current = true;

        const timer = window.setTimeout(() => {
            void finishExam({
                timeout: true,
            });
        }, 0);

        return () => {
            window.clearTimeout(timer);
        };
    }, [
        remainingSeconds,
        submitted,
        saving,
        isPaused,
        exam,
        questions,
        finishExam,
    ]);

    /* =========================================
       PAUSE / RESUME BUTTON
    ========================================= */

    function handlePause() {
        if (
            submitted ||
            saving ||
            remainingSeconds <= 0
        ) {
            return;
        }

        if (isPaused) {
            updatePaused(false);

            setSaveError("");

            setSaveMessage(
                "Exam resumed."
            );

            return;
        }

        void savePause();
    }

    /* =========================================
       SUBMIT BUTTON
    ========================================= */

    function handleSubmit() {
        if (
            saving ||
            submitted ||
            requestRef.current
        ) {
            return;
        }

        void finishExam({
            timeout: false,
        });
    }

    /* =========================================
       CLOSE RESULT MODAL
    ========================================= */

    function handleResultClose() {
        // Close only.
        // Do not navigate automatically.
        setResultModalOpen(false);
    }

    /* =========================================
       VIEW EXAM ANALYSIS
    ========================================= */

    function handleViewAnalysis() {
        const savedAttemptId =
            pauseId ||
            getAttemptId(submittedResult);

        if (!savedAttemptId) {
            setSaveError(
                "Saved attempt ID is missing. Unable to open exam analysis."
            );
            return;
        }

        const resolvedExamTitle =
            getMockExamTitle({
                exam,
                submittedResult,
                fallback: examTitle,
            });

        const params =
            new URLSearchParams({
                attemptId: String(
                    savedAttemptId
                ),

                examType,

                ...(resolvedExamTitle
                    ? {
                        title: resolvedExamTitle,
                    }
                    : {}),
            });

        const analysisPath =
            `/dashboard/${governmentExamsSlug}` +
            `/exam-analysis?${params.toString()}`;

        setSaveError("");
        setResultModalOpen(false);

        router.push(analysisPath);
    }

    /* =========================================
       RETURN
    ========================================= */

    return {
        saving,
        submitted,

        pauseId,
        isPaused,

        saveMessage,
        saveError,

        resultModalOpen,
        submittedResult,
        resultLoading,

        handlePause,
        handleSubmit,

        handleResultClose,
        handleViewAnalysis,

        finishExam,
    };
}

