"use client";

import {
  useEffect,
  useRef,
  useState,
} from "react";

import {
  useRouter,
} from "next/navigation";

import ExamHero from "./ExamHero";
import ExamTimer from "./ExamTimer";
import ExamProgress from "./ExamProgress";
import ExamQuestionRange from "./ExamQuestionRange";
import ExamQuestions from "./ExamQuestions";
import ExamPagination from "./ExamPagination";
import ExamPause from "./ExamPause";
import ExamSubmit from "./ExamSubmit";
import ExamResult from "./ExamResult";
import ExamEmpty from "./ExamEmpty";

import useExamController from "./hooks/useExamController";

import PyqResultModal from "@/components/PyqResultModal";
import ExamPauseConfirmModal from "@/components/ExamPauseConfirmModal";

import {
  clearGuestExamHandoff,
  readGuestExamHandoff,
} from "@/lib/guestExamHandoff";

export default function ExamClient({
  exam,
  examId,
  questions = [],
  imagePath = "",
  uid = 0,
  cid,
  examType = "pqp",
  lastPosition,
  initialPauseId = null,
  governmentExamsSlug = "",
  guestAction = "",
}) {
  const router = useRouter();

  const id = examId ?? exam?.id;

  const handoff = [
    "pause",
    "submit",
  ].includes(guestAction);

  const [restored, setRestored] = useState(
    !handoff
  );

  const [
    restoreError,
    setRestoreError,
  ] = useState("");

  const restoredOnce = useRef(false);
  const appliedOnce = useRef(false);
  const autoSubmitted = useRef(false);
  const resumedQuestionScrolled = useRef(false);

  const [
    showPauseConfirmation,
    setShowPauseConfirmation,
  ] = useState(false);

  const controller = useExamController({
    exam,
    examId: id,
    questions,
    uid,
    cid,
    examType,
    lastPosition,
    initialPauseId,
    governmentExamsSlug,
    guestAction,
  });

  function handlePauseAndReturn() {
    setShowPauseConfirmation(true);
  }

  async function savePauseAndReturn() {
    const saved = await controller.handlePause();

    if (saved) {
      clearGuestExamHandoff();

      router.replace(
        `/dashboard/${encodeURIComponent(
          governmentExamsSlug
        )}`
      );
    }

    return Boolean(saved);
  }

  async function confirmPauseAndReturn() {
    const saved = await savePauseAndReturn();

    if (saved) {
      setShowPauseConfirmation(false);
    }
  }

  useEffect(() => {
    restoredOnce.current = false;
    appliedOnce.current = false;
    autoSubmitted.current = false;
    resumedQuestionScrolled.current = false;
  }, [
    id,
    guestAction,
    handoff,
  ]);

  /* SCROLL TO RESTORED QUESTION */

  useEffect(() => {
    if (
      !initialPauseId ||
      !controller.restoreReady ||
      !controller.lastAnsweredQuestionId ||
      resumedQuestionScrolled.current
    ) {
      return;
    }

    const timer = window.setTimeout(() => {
      const question = document.getElementById(
        `exam-question-${controller.lastAnsweredQuestionId}`
      );

      if (question) {
        question.scrollIntoView({
          behavior: "smooth",
          block: "center",
        });

        resumedQuestionScrolled.current = true;
      }
    }, 0);

    return () => window.clearTimeout(timer);
  }, [
    initialPauseId,
    controller.restoreReady,
    controller.lastAnsweredQuestionId,
  ]);

  /* RESTORE GUEST ATTEMPT */

  useEffect(() => {
    if (
      !handoff ||
      restoredOnce.current
    ) {
      return;
    }

    const timer = window.setTimeout(() => {
      if (restoredOnce.current) return;

      restoredOnce.current = true;

      try {
        const saved = readGuestExamHandoff({
          examId: id,
          examType,
          governmentExamsSlug,
        });

        if (
          !saved ||
          saved.action !== guestAction
        ) {
          throw new Error(
            "Saved exam progress could not be found. Return to the original exam tab."
          );
        }

        controller.restoreGuestAttempt(saved);
        setRestored(true);
      } catch (error) {
        setRestoreError(
          error.message ||
          "Unable to restore this exam."
        );
      }
    }, 0);

    return () => window.clearTimeout(timer);
  }, [
    handoff,
    id,
    examType,
    governmentExamsSlug,
    guestAction,
    controller.restoreGuestAttempt,
  ]);

  /* SHOW PAUSE CONFIRMATION AFTER LOGIN */

  useEffect(() => {
    if (
      !handoff ||
      !restored ||
      restoreError ||
      !controller.restoreReady ||
      appliedOnce.current
    ) {
      return;
    }

    appliedOnce.current = true;

    if (controller.submitted) return;

    if (guestAction === "submit") {
      void controller.handleSubmit();
    } else {
      setShowPauseConfirmation(true);
    }
  }, [
    handoff,
    restored,
    restoreError,
    guestAction,
    controller.restoreReady,
    controller.submitted,
    controller.handleSubmit,
  ]);

  /* AUTOMATIC FINISH */

  useEffect(() => {
    if (
      !restored ||
      restoreError ||
      handoff ||
      !controller.timerFinished ||
      controller.submitted ||
      controller.saving ||
      autoSubmitted.current
    ) {
      return;
    }

    autoSubmitted.current = true;
    controller.handleSubmit();
  }, [
    restored,
    restoreError,
    handoff,
    controller.timerFinished,
    controller.submitted,
    controller.saving,
    controller.handleSubmit,
  ]);

  function viewAttempted() {
    if (!governmentExamsSlug) return;

    try {
      clearGuestExamHandoff();
    } catch {
      // Attempt is already saved to the backend.
    }

    router.push(
      `/dashboard/${encodeURIComponent(
        governmentExamsSlug
      )}/exam-attempted`
    );
  }

  if (restoreError) {
    return (
      <p
        role="alert"
        className="rounded-xl bg-red-50 p-5 text-red-700"
      >
        {restoreError}
      </p>
    );
  }

  if (
    !restored ||
    !controller.restoreReady
  ) {
    return (
      <div
        role={controller.saveError ? "alert" : "status"}
        className="rounded-xl bg-white p-5"
      >
        {controller.saveError ? (
          <>
            <p className="text-red-700">
              {controller.saveError}
            </p>

            <button
              type="button"
              className="mt-3 font-semibold text-blue-700 underline"
              onClick={() => window.location.reload()}
            >
              Retry loading saved exam
            </button>
          </>
        ) : (
          "Restoring your saved exam…"
        )}
      </div>
    );
  }

  if (!controller.totalQuestions) {
    return <ExamEmpty />;
  }

  const c = controller;

  return (
    <>
      <section className="space-y-6">
        {c.saveError && (
          <p
            role="alert"
            className="rounded-xl bg-red-50 p-4 text-red-700"
          >
            {c.saveError} Your answers are retained.
            Use the action button to retry.
          </p>
        )}

        {c.paused && (
          <p
            role="status"
            className="rounded-xl bg-amber-50 p-4"
          >
            Exam paused. Answers and remaining time
            are saved.
          </p>
        )}

        <ExamHero
          exam={exam}
          totalQuestions={c.totalQuestions}
          currentPage={c.currentPage}
          totalPages={c.totalPages}
        />

        {c.durationMinutes > 0 && (
          <div className="flex justify-end">
            <ExamTimer
              remainingSeconds={c.remainingSeconds}
              durationMinutes={c.durationMinutes}
            />
          </div>
        )}

        {c.submitted && (
          <ExamResult
            totalQuestions={c.totalQuestions}
            answeredCount={c.answeredCount}
            correctCount={c.correctCount}
            wrongCount={c.wrongCount}
          />
        )}

        <ExamProgress
          answeredCount={c.answeredCount}
          totalQuestions={c.totalQuestions}
          progress={c.progress}
        />

        <ExamQuestionRange
          startIndex={c.startIndex}
          endIndex={c.endIndex}
          totalQuestions={c.totalQuestions}
          currentPage={c.currentPage}
          unansweredCount={c.unansweredCount}
        />

        <div
          className={
            c.saving ||
              c.paused ||
              showPauseConfirmation ||
              c.interactionFrozen ||
              c.submitted
              ? "pointer-events-none"
              : ""
          }
        >
          <ExamQuestions
            questions={c.currentQuestions}
            startIndex={c.startIndex}
            answers={c.answers}
            submitted={c.submitted}
            imagePath={imagePath}
            onAnswer={c.handleAnswer}
          />
        </div>

        <ExamPagination
          currentPage={c.currentPage}
          totalPages={c.totalPages}
          onPrevious={c.handlePreviousPage}
          onNext={c.handleNextPage}
          onPageChange={c.handlePageChange}
        />

        {!c.submitted && (
          <div className="flex flex-col gap-3 sm:flex-row sm:justify-end">
            {guestAction !== "submit" && (
              <ExamPause
                paused={c.paused}
                disabled={
                  !c.restoreReady ||
                  c.timerFinished ||
                  c.saving
                }
                onPause={handlePauseAndReturn}
                saving={c.saving}
              />
            )}

            <ExamSubmit
              answeredCount={c.answeredCount}
              totalQuestions={c.totalQuestions}
              onSubmit={c.handleSubmit}
              saving={c.saving}
            />
          </div>
        )}

        {c.timerFinished && !c.submitted && (
          <p
            role="status"
            className="rounded-xl bg-red-50 p-4 text-red-700"
          >
            Exam time has ended.{" "}
            {c.saveError
              ? "Use Submit & Finish to retry."
              : "Saving your exam…"}
          </p>
        )}

        {c.submitted && (
          <button
            type="button"
            onClick={() => c.handleSubmit()}
            className="rounded-xl bg-blue-700 px-5 py-3 font-bold text-white"
          >
            Show Result
          </button>
        )}
      </section>

      <PyqResultModal
        open={c.resultModalOpen}
        result={c.submittedResult}
        examTitle={
          exam?.exam_name ??
          exam?.title ??
          "Previous Questions"
        }
        onClose={c.closeResultModal}
        onViewAnalysis={viewAttempted}
      />

      <ExamPauseConfirmModal
        open={showPauseConfirmation}
        saving={controller.saving}
        onClose={() => {
          setShowPauseConfirmation(false);
          controller.continueRestoredExam();
        }}
        onConfirm={confirmPauseAndReturn}
      />
    </>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import { normalizeQuestions } from "../utils/examUtils";

import {
  calculateExamResult,
  getAttemptId,
  normalizeExamAnswer,
  parseAnswers,
  savedPausedTimeToSeconds,
  timestampToMilliseconds,
} from "@/lib/examAttemptData";

import {
  saveGuestExamHandoff,
  guestExamLoginRedirectPath,
} from "@/lib/guestExamHandoff";

const QUESTIONS_PER_PAGE = 10;

function positiveId(value) {
  const number = Number(value);

  return Number.isSafeInteger(number) && number > 0
    ? number
    : null;
}

function isFailed(value) {
  return [
    false,
    0,
    "0",
    "false",
    "error",
    "failed",
  ].includes(value);
}

function getQuestionIndex(questions, questionId) {
  if (questionId == null) return -1;

  return questions.findIndex(
    (question) =>
      String(question.id) === String(questionId)
  );
}

function getLastAnsweredIndex(questions, answers) {
  return questions.reduce((last, question, index) => {
    const answer = normalizeExamAnswer(
      answers?.[question.id]
    );

    return /^[A-D]$/.test(answer)
      ? index
      : last;
  }, -1);
}

function clampPage(page, totalQuestions) {
  const maxPage = Math.max(
    1,
    Math.ceil(totalQuestions / QUESTIONS_PER_PAGE)
  );

  const value = Number(page);

  return Math.min(
    maxPage,
    Math.max(
      1,
      Number.isSafeInteger(value) ? value : 1
    )
  );
}

async function postAttempt(endpoint, payload) {
  const response = await fetch(endpoint, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  });

  let result;

  try {
    result = await response.json();
  } catch {
    throw new Error(
      "Exam API returned an invalid response."
    );
  }

  if (
    !response.ok ||
    !result ||
    isFailed(result.status)
  ) {
    const error = new Error(
      result?.message ||
      result?.msg ||
      "Unable to save this exam."
    );

    error.status = response.status;

    throw error;
  }

  return result;
}

export default function useExamController({
  exam,
  examId,
  questions = [],
  uid,
  cid,
  examType = "pqp",
  lastPosition,
  initialPauseId = null,
  governmentExamsSlug = "",
  guestAction = "",
}) {
  const id = examId ?? exam?.id;

  const type = ["pyq", "pqp"].includes(
    String(examType).toLowerCase()
  )
    ? "pqp"
    : String(examType).toLowerCase();

  const isGuestHandoff = [
    "pause",
    "submit",
  ].includes(guestAction);

  const normalizedQuestions = useMemo(
    () => normalizeQuestions(questions),
    [questions]
  );

  const totalQuestions = normalizedQuestions.length;

  const durationMinutes = Math.max(
    0,
    Number(
      exam?.total_minutes ??
      exam?.duration ??
      exam?.exam_duration ??
      0
    ) || 0
  );

  const totalDurationSeconds = Math.round(
    durationMinutes * 60
  );

  const draftKey =
    `exam_draft_${uid}_${cid}_${type}_${id}`;

  const [currentPage, setCurrentPage] = useState(1);
  const [answers, setAnswers] = useState({});

  const [
    lastAnsweredQuestionId,
    setLastAnsweredQuestionId,
  ] = useState(null);

  const [submitted, setSubmitted] = useState(false);
  const [saving, setSaving] = useState(false);
  const [paused, setPaused] = useState(false);
  const [saveError, setSaveError] = useState("");

  const [
    remainingSeconds,
    setRemainingSeconds,
  ] = useState(totalDurationSeconds);

  const [
    resultModalOpen,
    setResultModalOpen,
  ] = useState(false);

  const [
    submittedResult,
    setSubmittedResult,
  ] = useState(null);

  const [
    restoreReady,
    setRestoreReady,
  ] = useState(
    !initialPauseId && !isGuestHandoff
  );

  const [
    interactionFrozen,
    setInteractionFrozen,
  ] = useState(isGuestHandoff);

  const [initialStartTime] = useState(Date.now);
  const lock = useRef(false);

  const attempt = useRef({
    answers: {},
    lastAnsweredQuestionId: null,
    currentPage: 1,
    remainingSeconds: totalDurationSeconds,
    startTime: initialStartTime,
    endTime: null,
    pauseId: initialPauseId,
    boundUid: null,
    submittedResult: null,
    frozen: isGuestHandoff,
  });

  /* =====================================================
     RESTORE NORMAL OR PREVIOUSLY PAUSED EXAM
  ===================================================== */

  useEffect(() => {
    if (isGuestHandoff) return;

    let cancelled = false;

    async function restoreExam() {
      let savedDraft = null;
      let restoreFailure = "";

      if (initialPauseId) {
        try {
          const draft = JSON.parse(
            localStorage.getItem(draftKey) || "null"
          );

          if (
            draft &&
            String(draft.pauseId) ===
              String(initialPauseId)
          ) {
            savedDraft = draft;
          }
        } catch (error) {
          console.warn(
            "Unable to restore local PYQ draft:",
            error
          );
        }
      }

      if (initialPauseId && !savedDraft) {
        try {
          const response = await fetch(
            "/api/exam-attempt/analytics-details",
            {
              method: "POST",
              headers: {
                "Content-Type": "application/json",
              },
              cache: "no-store",
              body: JSON.stringify({
                cid,
                id: initialPauseId,
                exam_type: type,
              }),
            }
          );

          const result = await response.json();

          if (
            !response.ok ||
            isFailed(result?.status)
          ) {
            throw new Error(
              result?.message ||
              "Unable to load the saved attempt."
            );
          }

          const candidates = [
            result?.details,
            result?.data,
            result?.result,
            result?.results,
          ];

          const rows = candidates.find(Array.isArray);

          const savedAttempt =
            rows?.find(
              (row) =>
                String(
                  row?.pauseid ??
                  row?.pause_id ??
                  row?.attempt_id ??
                  row?.id
                ) === String(initialPauseId)
            ) ??
            (
              result?.data &&
              !Array.isArray(result.data) &&
              typeof result.data === "object"
                ? result.data
                : null
            );

          if (!savedAttempt) {
            throw new Error(
              "Saved attempt details were not returned."
            );
          }

          const savedAnswers = parseAnswers(
            savedAttempt.user_answers ??
            savedAttempt.answers
          );

          const restoredAnswers = {};

          normalizedQuestions.forEach(
            (question, index) => {
              const answer = normalizeExamAnswer(
                savedAnswers[index]
              );

              if (/^[A-D]$/.test(answer)) {
                restoredAnswers[question.id] = answer;
              }
            }
          );

          const savedPosition = Number(
            savedAttempt.lastposition ??
            savedAttempt.last_position
          );

          const positionIndex =
            Number.isSafeInteger(savedPosition) &&
            savedPosition > 0
              ? savedPosition - 1
              : -1;

          const lastAnsweredIndex =
            getLastAnsweredIndex(
              normalizedQuestions,
              restoredAnswers
            );

          const resumeIndex =
            positionIndex >= 0 &&
            positionIndex < totalQuestions
              ? positionIndex
              : lastAnsweredIndex;

          const lastQuestionId =
            resumeIndex >= 0
              ? normalizedQuestions[resumeIndex]?.id
              : null;

          const savedPage = Number(
            savedAttempt.current_page ??
            savedAttempt.currentPage
          );

          savedDraft = {
            answers: restoredAnswers,
            lastAnsweredQuestionId: lastQuestionId,
            pauseId: initialPauseId,

            remainingSeconds:
              savedAttempt.paused_time == null
                ? totalDurationSeconds
                : savedPausedTimeToSeconds(
                    savedAttempt.paused_time,
                    totalDurationSeconds
                  ),

            currentPage:
              Number.isSafeInteger(savedPage) &&
              savedPage > 0
                ? savedPage
                : Math.floor(
                    Math.max(0, resumeIndex) /
                    QUESTIONS_PER_PAGE
                  ) + 1,

            startTime:
              timestampToMilliseconds(
                savedAttempt.start_time ??
                savedAttempt.startTime ??
                savedAttempt.started_at
              ) ?? Date.now(),
          };

          try {
            localStorage.setItem(
              draftKey,
              JSON.stringify(savedDraft)
            );
          } catch (error) {
            console.warn(
              "Unable to cache restored PYQ attempt:",
              error
            );
          }
        } catch (error) {
          restoreFailure =
            error?.message ||
            "Unable to restore the saved attempt.";
        }
      }

      if (cancelled) return;

      if (initialPauseId && !savedDraft) {
        setSaveError(restoreFailure);
        setRestoreReady(false);
        return;
      }

      const restoredAnswers =
        savedDraft?.answers &&
        typeof savedDraft.answers === "object" &&
        !Array.isArray(savedDraft.answers)
          ? savedDraft.answers
          : {};

      const questionIndex = getQuestionIndex(
        normalizedQuestions,
        savedDraft?.lastAnsweredQuestionId
      );

      const lastIndex =
        questionIndex >= 0
          ? questionIndex
          : getLastAnsweredIndex(
              normalizedQuestions,
              restoredAnswers
            );

      const lastQuestionId =
        lastIndex >= 0
          ? normalizedQuestions[lastIndex]?.id
          : null;

      const savedPage = Number(
        savedDraft?.currentPage
      );

      const fallbackPage =
        lastIndex >= 0
          ? Math.floor(
              lastIndex / QUESTIONS_PER_PAGE
            ) + 1
          : 1;

      const restoredPage = clampPage(
        Number.isSafeInteger(savedPage) &&
          savedPage > 0
          ? savedPage
          : fallbackPage,
        totalQuestions
      );

      const savedRemaining = Number(
        savedDraft?.remainingSeconds
      );

      const restoredRemaining =
        Number.isFinite(savedRemaining)
          ? Math.min(
              totalDurationSeconds,
              Math.max(0, savedRemaining)
            )
          : totalDurationSeconds;

      attempt.current = {
        answers: restoredAnswers,
        lastAnsweredQuestionId: lastQuestionId,
        currentPage: restoredPage,
        remainingSeconds: restoredRemaining,
        startTime:
          Number(savedDraft?.startTime) ||
          Date.now(),
        endTime: null,
        pauseId: initialPauseId,
        boundUid: positiveId(uid),
        submittedResult: null,
        frozen: false,
      };

      setAnswers(restoredAnswers);
      setLastAnsweredQuestionId(lastQuestionId);
      setCurrentPage(restoredPage);
      setRemainingSeconds(restoredRemaining);

      setSubmitted(false);
      setPaused(false);
      setSaving(false);
      setSaveError("");
      setSubmittedResult(null);
      setResultModalOpen(false);
      setInteractionFrozen(false);
      setRestoreReady(true);
    }

    void restoreExam();

    return () => {
      cancelled = true;
    };
  }, [
    id,
    cid,
    uid,
    type,
    draftKey,
    normalizedQuestions,
    totalQuestions,
    totalDurationSeconds,
    initialPauseId,
    isGuestHandoff,
  ]);

  /* =====================================================
     RESTORE GUEST ATTEMPT AFTER LOGIN
  ===================================================== */

  const restoreGuestAttempt = useCallback(
    (saved) => {
      if (
        String(saved?.examId) !== String(id) ||
        String(saved?.examType).toLowerCase() !== type ||
        String(saved?.governmentExamsSlug) !==
          governmentExamsSlug ||
        Number(saved?.cid) !== Number(cid)
      ) {
        throw new Error(
          "Saved exam does not match this test."
        );
      }

      if (
        !saved.answers ||
        typeof saved.answers !== "object" ||
        Array.isArray(saved.answers)
      ) {
        throw new Error(
          "Saved answers are invalid."
        );
      }

      const questionIds = normalizedQuestions.map(
        (question) => String(question.id)
      );

      if (
        !Array.isArray(saved.questionIds) ||
        JSON.stringify(saved.questionIds) !==
          JSON.stringify(questionIds)
      ) {
        throw new Error(
          "The question paper changed. Saved progress cannot be restored safely."
        );
      }

      const savedRemaining = Number(
        saved.remainingSeconds
      );

      if (
        !Number.isFinite(savedRemaining) ||
        savedRemaining < 0 ||
        savedRemaining > totalDurationSeconds ||
        !Number.isFinite(Number(saved.startTime))
      ) {
        throw new Error(
          "Saved exam timing is invalid."
        );
      }

      const currentUid = positiveId(uid);

      if (!currentUid) {
        throw new Error(
          "Please complete login before restoring this exam."
        );
      }

      if (
        saved.boundUid &&
        Number(saved.boundUid) !== currentUid
      ) {
        throw new Error(
          "This attempt belongs to another signed-in account."
        );
      }

      const savedQuestionIndex = getQuestionIndex(
        normalizedQuestions,
        saved.lastAnsweredQuestionId
      );

      const lastIndex =
        savedQuestionIndex >= 0
          ? savedQuestionIndex
          : getLastAnsweredIndex(
              normalizedQuestions,
              saved.answers
            );

      const lastQuestionId =
        lastIndex >= 0
          ? normalizedQuestions[lastIndex]?.id
          : null;

      const savedPage = Number(saved.currentPage);

      const fallbackPage =
        lastIndex >= 0
          ? Math.floor(
              lastIndex / QUESTIONS_PER_PAGE
            ) + 1
          : 1;

      const restoredPage = clampPage(
        Number.isSafeInteger(savedPage) &&
          savedPage > 0
          ? savedPage
          : fallbackPage,
        totalQuestions
      );

      const restoredAnswers = {
        ...saved.answers,
      };

      attempt.current = {
        answers: restoredAnswers,
        lastAnsweredQuestionId: lastQuestionId,
        currentPage: restoredPage,
        remainingSeconds: savedRemaining,
        startTime: Number(saved.startTime),
        endTime: saved.endTime ?? null,
        pauseId: positiveId(saved.pauseId),
        boundUid: currentUid,
        submittedResult:
          saved.submittedResult ?? null,
        frozen: true,
      };

      setAnswers(restoredAnswers);
      setLastAnsweredQuestionId(lastQuestionId);
      setCurrentPage(restoredPage);
      setRemainingSeconds(savedRemaining);

      setInteractionFrozen(true);
      setRestoreReady(true);
      setSaveError("");

      if (saved.submittedResult) {
        setSubmitted(true);
        setSubmittedResult(saved.submittedResult);
        setResultModalOpen(true);
      }

      return saved;
    },
    [
      id,
      type,
      governmentExamsSlug,
      cid,
      uid,
      normalizedQuestions,
      totalDurationSeconds,
      totalQuestions,
    ]
  );

  /* =====================================================
     CONTINUE EXAM AFTER CANCELING PAUSE
  ===================================================== */

  const continueRestoredExam = useCallback(() => {
    if (
      attempt.current.submittedResult ||
      lock.current
    ) {
      return;
    }

    attempt.current.frozen = false;
    setInteractionFrozen(false);
  }, []);

  /* =====================================================
     TIMER
  ===================================================== */

  useEffect(() => {
    if (
      !restoreReady ||
      submitted ||
      paused ||
      saving ||
      interactionFrozen ||
      totalDurationSeconds <= 0
    ) {
      return;
    }

    let lastTick = Date.now();

    const timer = window.setInterval(() => {
      if (
        attempt.current.frozen ||
        lock.current
      ) {
        lastTick = Date.now();
        return;
      }

      const now = Date.now();

      const elapsed = Math.floor(
        (now - lastTick) / 1000
      );

      if (elapsed < 1) return;

      lastTick += elapsed * 1000;

      attempt.current.remainingSeconds = Math.max(
        0,
        attempt.current.remainingSeconds - elapsed
      );

      setRemainingSeconds(
        attempt.current.remainingSeconds
      );
    }, 250);

    return () => window.clearInterval(timer);
  }, [
    restoreReady,
    submitted,
    paused,
    saving,
    interactionFrozen,
    totalDurationSeconds,
  ]);

  /* =====================================================
     ANSWERS AND SCORING
  ===================================================== */

  const answerArray = useMemo(
    () =>
      normalizedQuestions.map(
        (question) =>
          question.answerkey ??
          question.answer ??
          question.correct_answer ??
          question.correctAnswer ??
          0
      ),
    [normalizedQuestions]
  );

  const markTotal = Number(
    exam?.total_mark ??
    exam?.total_marks ??
    exam?.mark
  );

  const totalMark =
    Number.isFinite(markTotal) && markTotal > 0
      ? markTotal
      : totalQuestions;

  const markPerCorrect = 1;
  const negativeMarkPerWrong = 0.333;

  const statsFor = useCallback(
    (selected) =>
      calculateExamResult({
        answerArray,
        userAnswers: normalizedQuestions.map(
          (question) =>
            selected[question.id] ?? 0
        ),
        markPerCorrect,
        negativeMarkPerWrong,
      }),
    [answerArray, normalizedQuestions]
  );

  const stats = useMemo(
    () => statsFor(answers),
    [answers, statsFor]
  );

  const answeredCount = useMemo(
    () =>
      normalizedQuestions.filter(
        (question) => {
          const answer = normalizeExamAnswer(
            answers[question.id]
          );

          return /^[A-D]$/.test(answer);
        }
      ).length,
    [answers, normalizedQuestions]
  );

  /* =====================================================
     SAVE GUEST CHECKPOINT
  ===================================================== */

  function checkpoint(action) {
    return saveGuestExamHandoff({
      ...attempt.current,
      examId: id,
      examType: type,
      cid,
      governmentExamsSlug,
      action,
      currentPage: attempt.current.currentPage,

      questionIds: normalizedQuestions.map(
        (question) => String(question.id)
      ),
    });
  }

  /* =====================================================
     SAVE PAUSE OR SUBMIT
  ===================================================== */

  async function save(action) {
    if (
      lock.current ||
      !restoreReady ||
      submitted ||
      paused
    ) {
      if (submitted && attempt.current.submittedResult) {
        setResultModalOpen(true);
        return true;
      }

      return false;
    }

    lock.current = true;
    setSaving(true);
    setSaveError("");

    const wasFrozen = attempt.current.frozen;

    attempt.current.frozen = true;
    setInteractionFrozen(true);

    if (action === "submit") {
      attempt.current.endTime ??= Date.now();
    }

    let success = false;
    let redirecting = false;

    try {
      if (!positiveId(uid)) {
        checkpoint(action);

        const destination =
          guestExamLoginRedirectPath(action);

        redirecting = true;

        window.location.assign(
          `/login?redirect=${encodeURIComponent(
            destination
          )}`
        );

        return false;
      }

      const current = attempt.current;

      const resultStats = statsFor(
        current.answers
      );

      const lastAnsweredIndex = getQuestionIndex(
        normalizedQuestions,
        current.lastAnsweredQuestionId
      );

      const resumePosition =
        lastAnsweredIndex >= 0
          ? lastAnsweredIndex + 1
          : (
              current.currentPage - 1
            ) * QUESTIONS_PER_PAGE + 1;

      const payload = {
        cid,
        exam_id: id,
        exam_type: type,
        lastposition: resumePosition,

        total_questions: totalQuestions,
        total_mark: totalMark,

        remaining_seconds:
          current.remainingSeconds,

        start_time:
          current.startTime,

        ...(action === "submit"
          ? { end_time: current.endTime }
          : {}),

        answer_array: answerArray,

        user_answers: normalizedQuestions.map(
          (question) =>
            current.answers[question.id] ?? 0
        ),

        total_attempted: resultStats.attempted,
        total_correct: resultStats.correct,
        total_wrong: resultStats.wrong,
        user_score: resultStats.score,
        minus_mark: resultStats.negativeMark,

        __scoring: {
          markPerCorrect,
          negativeMarkPerWrong,
        },
      };

      const isResuming = Boolean(current.pauseId);

      const result = await postAttempt(
        "/api/pyq-attempt",
        {
          ...payload,
          action: isResuming
            ? "update"
            : "create",

          exam_status:
            action === "submit"
              ? "finish"
              : "pause",

          ...(isResuming
            ? { pauseid: current.pauseId }
            : {}),
        }
      );

      if (!isResuming) {
        const savedId = positiveId(
          getAttemptId(result)
        );

        if (!savedId) {
          throw new Error(
            "The backend saved the attempt but did not return its ID. Please contact support before retrying."
          );
        }

        current.pauseId = savedId;
        current.boundUid = Number(uid);
      }

      success = true;

      if (action === "pause") {
        try {
          localStorage.setItem(
            draftKey,
            JSON.stringify({
              answers: current.answers,

              lastAnsweredQuestionId:
                current.lastAnsweredQuestionId,

              pauseId: current.pauseId,

              remainingSeconds:
                current.remainingSeconds,

              currentPage:
                current.currentPage,

              startTime:
                current.startTime,
            })
          );
        } catch (error) {
          console.warn(
            "Unable to cache paused exam:",
            error
          );
        }

        setPaused(true);
      } else {
        try {
          localStorage.removeItem(draftKey);
        } catch (error) {
          console.warn(
            "Unable to clear finished exam draft:",
            error
          );
        }

        const finalResult = {
          ...payload,
          ...result.savedResult,

          id: current.pauseId,
          pauseid: current.pauseId,
          exam_status: "finish",

          exam_name:
            exam?.exam_name ??
            exam?.title ??
            "",

          status: true,
        };

        current.submittedResult = finalResult;

        setSubmittedResult(finalResult);
        setSubmitted(true);
        setResultModalOpen(true);

        if (isGuestHandoff) {
          try {
            checkpoint("submit");
          } catch {
            // Backend result has already been saved.
          }
        }
      }

      return result;
    } catch (error) {
      if (error.status === 401) {
        try {
          checkpoint(action);

          const destination =
            guestExamLoginRedirectPath(action);

          redirecting = true;

          window.location.assign(
            `/login?redirect=${encodeURIComponent(
              destination
            )}`
          );
        } catch (storageError) {
          setSaveError(
            storageError.message ||
            "Unable to preserve exam progress."
          );
        }
      } else {
        setSaveError(
          error.message ||
          "Unable to save this exam. Please retry."
        );
      }

      return false;
    } finally {
      lock.current = false;
      setSaving(false);

      if (!success && !redirecting) {
        attempt.current.frozen = wasFrozen;
        setInteractionFrozen(wasFrozen);
      }
    }
  }

  /* =====================================================
     PAGINATION
  ===================================================== */

  const totalPages = Math.max(
    1,
    Math.ceil(
      totalQuestions / QUESTIONS_PER_PAGE
    )
  );

  const startIndex =
    (currentPage - 1) * QUESTIONS_PER_PAGE;

  function pageTo(page) {
    if (
      !restoreReady ||
      submitted ||
      paused ||
      saving ||
      interactionFrozen
    ) {
      return;
    }

    const nextPage = clampPage(
      page,
      totalQuestions
    );

    attempt.current.currentPage = nextPage;

    setCurrentPage(nextPage);

    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  }

  /* =====================================================
     ANSWER SELECTION
  ===================================================== */

  function handleAnswer(questionId, optionKey) {
    if (
      submitted ||
      paused ||
      saving ||
      !restoreReady ||
      interactionFrozen ||
      attempt.current.frozen ||
      (
        totalDurationSeconds > 0 &&
        attempt.current.remainingSeconds <= 0
      )
    ) {
      return;
    }

    const next = {
      ...attempt.current.answers,
      [questionId]: optionKey,
    };

    attempt.current.answers = next;
    attempt.current.lastAnsweredQuestionId = questionId;

    setAnswers(next);
    setLastAnsweredQuestionId(questionId);
  }

  /* =====================================================
     RETURN CONTROLLER
  ===================================================== */

  return {
    currentPage,
    totalPages,
    startIndex,
    lastAnsweredQuestionId,

    endIndex: Math.min(
      startIndex + QUESTIONS_PER_PAGE,
      totalQuestions
    ),

    currentQuestions:
      normalizedQuestions.slice(
        startIndex,
        startIndex + QUESTIONS_PER_PAGE
      ),

    totalQuestions,
    answers,

    answeredCount,

    unansweredCount:
      totalQuestions - answeredCount,

    progress:
      totalQuestions > 0
        ? Math.round(
            (
              answeredCount /
              totalQuestions
            ) * 100
          )
        : 0,

    submitted,
    saving,
    paused,
    saveError,
    restoreReady,
    interactionFrozen,

    correctCount:
      submitted
        ? submittedResult?.total_correct ??
          stats.correct
        : 0,

    wrongCount:
      submitted
        ? submittedResult?.total_wrong ??
          stats.wrong
        : 0,

    durationMinutes,
    totalDurationSeconds,
    remainingSeconds,

    elapsedSeconds:
      totalDurationSeconds -
      remainingSeconds,

    timerFinished:
      restoreReady &&
      totalDurationSeconds > 0 &&
      remainingSeconds === 0,

    handleAnswer,

    handlePreviousPage:
      () => pageTo(currentPage - 1),

    handleNextPage:
      () => pageTo(currentPage + 1),

    handlePageChange: pageTo,

    handlePause:
      () => save("pause"),

    handleSubmit:
      () => save("submit"),

    restoreGuestAttempt,
    continueRestoredExam,

    resultModalOpen,
    submittedResult,

    closeResultModal:
      () => setResultModalOpen(false),
  };
}

